def _assert_cfg_snapshot_matches(expected_snapshot: dict[str, Any], actual_snapshot: dict[str, Any]) -> None:
    for field_name in ('test_start_date', 'test_end_date', 'future_horizon', 'sb_code'):
        _assert_strict_match(field_name, expected_snapshot[field_name], actual_snapshot[field_name])
    _assert_str_sequence_match('agent_profiles', expected_snapshot['agent_profiles'], actual_snapshot['agent_profiles'])
    _assert_int_sequence_match('agent_bus_ids', expected_snapshot['agent_bus_ids'], actual_snapshot['agent_bus_ids'])
    _assert_float_sequence_match('load_scale', expected_snapshot['load_scale'], actual_snapshot['load_scale'])
    _assert_float_sequence_match('pv_scale', expected_snapshot['pv_scale'], actual_snapshot['pv_scale'])
    _assert_float_sequence_match('battery_capacity', expected_snapshot['battery_capacity'], actual_snapshot['battery_capacity'])
    for field_name in ('line_max_loading_pct', 'v_min_pu', 'v_max_pu', 'max_charge_rate', 'efficiency', 'init_soc', 'soc_min', 'soc_max', 'soc_target', 'export_subsidy_eur_per_kwh', IMPORT_PRICE_MARKUP_KEY, 'branch_current_tiebreaker_eur_per_pu_step', 'physics_refinement_slack_ratio', 'physics_refinement_slack_abs_floor_eur', 'physics_refinement_aggressive_third_tier_ratio', 'physics_refinement_aggressive_third_tier_abs_floor_eur', 'physics_refinement_cap_utilization_trigger', 'physics_refinement_branch_l_gap_ratio_trigger', 'physics_refinement_time_limit_sec', 'physics_refinement_total_time_limit_sec', 'physics_refinement_target_mean_solver_gap_kw', 'physics_refinement_target_max_solver_gap_kw', 'physics_refinement_target_export_gap_ratio'):
        _assert_float_match(field_name, expected_snapshot[field_name], actual_snapshot[field_name])
    _assert_float_sequence_match('physics_refinement_slack_ratio_schedule', expected_snapshot['physics_refinement_slack_ratio_schedule'], actual_snapshot['physics_refinement_slack_ratio_schedule'])
    _assert_float_sequence_match('physics_refinement_slack_abs_floor_schedule_eur', expected_snapshot['physics_refinement_slack_abs_floor_schedule_eur'], actual_snapshot['physics_refinement_slack_abs_floor_schedule_eur'])
    for field_name in ('physics_refinement_mode', 'physics_refinement_enable_aggressive_third_tier', 'physics_refinement_use_full_start'):
        _assert_strict_match(field_name, expected_snapshot[field_name], actual_snapshot[field_name])

def _assert_full_input_structure_matches(expected_full_input: Any, actual_full_input: Any) -> None:
    _assert_strict_match('horizon_steps', int(expected_full_input.horizon_steps), int(actual_full_input.horizon_steps))
    _assert_int_sequence_match('episode_offsets', np.asarray(expected_full_input.episode_offsets, dtype=np.int32).tolist(), np.asarray(actual_full_input.episode_offsets, dtype=np.int32).tolist())
    _assert_int_sequence_match('episode_lengths', np.asarray(expected_full_input.episode_lengths, dtype=np.int32).tolist(), np.asarray(actual_full_input.episode_lengths, dtype=np.int32).tolist())
    _assert_int_sequence_match('episode_indices', np.asarray(expected_full_input.episode_indices, dtype=np.int32).tolist(), np.asarray(actual_full_input.episode_indices, dtype=np.int32).tolist())
    _assert_str_sequence_match('timestamps', [str(value) for value in tuple(expected_full_input.timestamps)], [str(value) for value in tuple(actual_full_input.timestamps)])

