def save_misocp_plan_package(package: dict[str, Any], target_dir: str | Path) -> Path:
    target_path = Path(target_dir).resolve()
    target_path.mkdir(parents=True, exist_ok=True)
    manifest = dict(package['manifest'])
    full_input = package['full_input']
    result = package['result']
    solve_summary = dict(package['solve_summary'])
    (target_path / 'manifest.json').write_text(json.dumps(manifest, indent=2, default=json_default), encoding='utf-8')
    (target_path / 'solve_summary.json').write_text(json.dumps(solve_summary, indent=2, default=json_default), encoding='utf-8')
    np.savez_compressed(target_path / 'full_input.npz', wholesale_price_seq=np.asarray(full_input.wholesale_price_seq, dtype=np.float32), import_price_seq=np.asarray(full_input.import_price_seq, dtype=np.float32), load_seq=np.asarray(full_input.load_seq, dtype=np.float32), pv_seq=np.asarray(full_input.pv_seq, dtype=np.float32), soc_init=np.asarray(full_input.soc_init, dtype=np.float32), timestamps=np.asarray(tuple(full_input.timestamps), dtype=np.str_), episode_offsets=np.asarray(full_input.episode_offsets, dtype=np.int32), episode_lengths=np.asarray(full_input.episode_lengths, dtype=np.int32), episode_indices=np.asarray(full_input.episode_indices, dtype=np.int32))
    np.savez_compressed(target_path / 'solve_result.npz', agent_net_grid_mw=np.asarray(result.agent_net_grid_mw, dtype=np.float32), agent_import_mw=np.asarray(result.agent_import_mw, dtype=np.float32), agent_export_mw=np.asarray(result.agent_export_mw, dtype=np.float32), battery_charge_mw=np.asarray(result.battery_charge_mw, dtype=np.float32), battery_discharge_mw=np.asarray(result.battery_discharge_mw, dtype=np.float32), pv_curtail_mw=np.asarray(result.pv_curtail_mw, dtype=np.float32), energy_mwh=np.asarray(result.energy_mwh, dtype=np.float32), branch_p_pu=np.asarray(result.branch_p_pu, dtype=np.float32), branch_q_pu=np.asarray(result.branch_q_pu, dtype=np.float32), branch_i2_pu=np.asarray(result.branch_i2_pu, dtype=np.float32), bus_v_sq=np.asarray(result.bus_v_sq, dtype=np.float32), root_import_mw=np.asarray(result.root_import_mw, dtype=np.float32), root_export_mw=np.asarray(result.root_export_mw, dtype=np.float32), root_p_kw=np.asarray(result.root_p_kw, dtype=np.float32), root_q_kvar=np.asarray(result.root_q_kvar, dtype=np.float32), bus_vm_pu=np.asarray(result.bus_vm_pu, dtype=np.float32), line_loading_pct=np.asarray(result.line_loading_pct, dtype=np.float32), trafo_loading_pct=np.asarray(result.trafo_loading_pct, dtype=np.float32), simultaneous_charge_discharge_kw=np.asarray(result.simultaneous_charge_discharge_kw, dtype=np.float32))
