def _validate_misocp_plan_package_dir(target_path: Path) -> None:
    required_names = ('manifest.json', 'full_input.npz', 'solve_result.npz', 'solve_summary.json')
    manifest_path = target_path / 'manifest.json'
    if not manifest_path.exists():
        raise FileNotFoundError(f'MISOCP plan package is incomplete at {target_path}: missing manifest.json.')
    try:
        manifest = json.loads(manifest_path.read_text(encoding='utf-8'))
    except json.JSONDecodeError as exc:
        raise ValueError(f'MISOCP plan package manifest is invalid JSON at {target_path}.') from exc
    version = int(manifest.get('plan_package_version', -1))
    missing_required = [name for name in required_names if not (target_path / name).exists()]
    if version != int(_PLAN_PACKAGE_VERSION) or missing_required:
        missing_display = f", missing={','.join(missing_required)}" if missing_required else ''
        raise ValueError(f'Exact MISOCP plan package is not compatible at {target_path}: version={version}, expected={_PLAN_PACKAGE_VERSION}{missing_display}. Re-run notebooks/madrl/global_MISOCP.ipynb to regenerate it.')

def resolve_exact_misocp_plan_package_dir(target_dir: str | Path) -> Path:
    return resolve_exact_rollout_package_dir(target_dir, package_label='MISOCP cached plan', missing_dir_hint='Please run notebooks/madrl/global_MISOCP.ipynb first and pass the exact package directory.', validate_package_dir=_validate_misocp_plan_package_dir)

